// PR c++/117512
// { dg-do run }

struct A {
  __attribute__((aligned(2 * sizeof (int)))) int i;
  ~A() {}
};

A foo () { A a = { 19 }; return a; }

int
main ()
{
  A a = { 42 };
  A r = foo () = a;
  if (r.i != 42)
    __builtin_abort ();
}

// PR c++/117512

struct A {
  __attribute__((aligned)) int b;
  ~A ();
};
A foo (int);

void
bar ()
{
  A e = { 0 };
  A d = foo (0) = e;
}

// PR c++/117512
// { dg-do compile { target c++11 } }

struct A {
  alignas(sizeof (long long)) int b;
  ~A ();
};
A foo (int);

void
bar ()
{
  A e = { 0 };
  A d = foo (0) = e;
}

// PR c++/117512

struct __attribute__((aligned (2 * sizeof (int)))) A {
  int b;
  ~A ();
};
A foo (int);

void
bar ()
{
  A e = { 0 };
  A d = foo (0) = e;
}
